export function normalizeTokenSubject(subject) {
    if ((subject.type === undefined || subject.type === 'token') &&
        typeof subject.token === 'string') {
        return { type: 'token', token: subject.token };
    }
    return subject;
}
export function normalizeTokenParams(params) {
    return {
        ...params,
        subject: normalizeTokenSubject(params.subject),
        scopes: params.scopes === undefined ? ['*'] : params.scopes,
    };
}
